440						}
441					}
442				}
443			}
444	
445			if ovalPack.NotFixedYet {
446				fixState = ovalFixStateForPackage(def, req.packName)
447				switch fixState {
448				case "Will not fix", "Under investigation":
449					return false, true, fixState, ovalPack.Version
450				default:
451					return true, true, fixState, ovalPack.Version
452				}
453			}
454	
455			// Compare between the installed version vs the version in OVAL
456			less, err := lessThan(family, req.versionRelease, ovalPack)
457			if err != nil {
458				logging.Log.Debugf("Failed to parse versions: %s, Ver: %#v, OVAL: %#v, DefID: %s",
459					err, req.versionRelease, ovalPack, def.DefinitionID)
460				return false, false, "", ovalPack.Version
461			}
462			if less {
463				if req.isSrcPack {
464					// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
465					return true, false, "", ovalPack.Version
466				}
467	
468				// If the version of installed is less than in OVAL
469				switch family {
470				case constant.RedHat,
471					constant.Fedora,
472					constant.Amazon,
473					constant.Oracle,
474					constant.OpenSUSE,
475					constant.OpenSUSELeap,
476					constant.SUSEEnterpriseServer,
477					constant.SUSEEnterpriseDesktop,
478					constant.Debian,
479					constant.Raspbian,
480					constant.Ubuntu:
481					// Use fixed state in OVAL for these distros.
482					return true, false, "", ovalPack.Version
483				}
484	
485				// But CentOS/Alma/Rocky can't judge whether fixed or unfixed.
486				// Because fixed state in RHEL OVAL is different.
487				// So, it have to be judged version comparison.
488	
489				// `offline` or `fast` scan mode can't get a updatable version.
490				// In these mode, the blow field was set empty.
491				// Vuls can not judge fixed or unfixed.
492				if req.newVersionRelease == "" {
493					return true, false, "", ovalPack.Version
494				}
495	
496				// compare version: newVer vs oval
497				less, err := lessThan(family, req.newVersionRelease, ovalPack)
498				if err != nil {
499					logging.Log.Debugf("Failed to parse versions: %s, NewVer: %#v, OVAL: %#v, DefID: %s",
500						err, req.newVersionRelease, ovalPack, def.DefinitionID)
501					return false, false, "", ovalPack.Version
502				}
503				return true, less, "", ovalPack.Version
504			}
505		}
506		return false, false, "", ""
507	}
508	
509	func ovalFixStateForPackage(def ovalmodels.Definition, packName string) string {
510		for _, resolution := range def.Advisory.AffectedResolution {
511			for _, component := range resolution.Components {
512				if component.Component == packName {
513					return resolution.State
514				}
515			}
 55	}
