 57	// NewGostClient make Client by family
 58	func NewGostClient(cnf config.GostConf, family string, o logging.LogOpts) (Client, error) {
 59		if family == constant.RedHat || family == constant.CentOS || family == constant.Rocky || family == constant.Alma {
 60			return Pseudo{}, nil
 61		}
 62	
 63		if err := gostlog.SetLogger(o.LogToFile, o.LogDir, o.Debug, o.LogJSON); err != nil {
 64			return nil, xerrors.Errorf("Failed to set gost logger. err: %w", err)
 65		}
 66	
 67		db, err := newGostDB(&cnf)
 68		if err != nil {
 69			return nil, xerrors.Errorf("Failed to newGostDB. err: %w", err)
 70		}
 71	
 72		base := Base{driver: db, baseURL: cnf.GetURL()}
 73		switch family {
 74		case constant.Debian, constant.Raspbian:
 75			return Debian{base}, nil
 76		case constant.Ubuntu:
 77			return Ubuntu{base}, nil
 78		case constant.Windows:
 79			return Microsoft{base}, nil
 80		default:
 81			return Pseudo{base}, nil
 82		}
